// lib/segment/src/types.rs line 589-598
#[serde(rename_all = "snake_case")]
pub struct SearchParams {
    /// Params relevant to HNSW index
    /// Size of the beam in a beam-search. Larger the value - more accurate the result, more time required for search.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub hnsw_ef: Option<usize>,

    /// Search without approximation. If set to true, search may run long but with exact results.
    #[serde(default)]
    pub exact: bool,

// lib/segment/src/index/hnsw_index/hnsw.rs line 1049-1051 (actual usage)
let ef = params
    .and_then(|params| params.hnsw_ef)
    .unwrap_or(self.config.ef);

// lib/collection/src/operations/verification/mod.rs line 99-108 (validation hook)
async fn check_search_params(
    &self,
    collection: &Collection,
    strict_mode_config: &StrictModeConfig,
) -> CollectionResult<()> {
    if let Some(search_params) = self.request_search_params() {
        Box::pin(search_params.check_strict_mode(collection, strict_mode_config)).await?;
    }
    Ok(())
}

